  "upgrade.providerConfirmNote": "As alterações de plano requerem a confirmação do fornecedor de faturação. Qualquer diferença de preço, acerto proporcional e data de entrada em vigor têm de ser mostrados antes de aprovar a alteração. Uma atualização não pode criar uma segunda subscrição simultânea.",
  "upgrade.chargedThroughProviderNote": "As alterações de plano são cobradas através do fornecedor de faturação. Pode cancelar a sua subscrição nesta página, utilizando o botão Cancelar Subscrição no seu plano atual, ou nas Definições. Cancelar interrompe as renovações futuras no fim do seu período pago; nunca termina o seu acesso de imediato. Os espaços de trabalho gratuitos existentes não são cobrados por ver estas opções.",
