  "exports.eyebrow": "Dados",
  "exports.title": "Exportações e cópias de segurança",
  "exports.subtitleStart": "As transferências estão sempre limitadas a",
  "exports.subtitleRest": ". Cada ficheiro é identificado com o nome da empresa e a data em que foi criado.",
  "exports.createBusinessFirst": "Crie primeiro uma empresa — as exportações pertencem a uma empresa, não à aplicação.",
  "exports.lockedTitle": "As exportações em CSV e Excel são uma funcionalidade do plano Business",
  "exports.lockedDesc": "O seu espaço de trabalho está no plano Essentials. O plano Business acrescenta exportações em CSV e Excel, valorização de stock, produtos e pessoal ilimitados, fornecedores, compras e pacotes.",
  "exports.seeBusiness": "Ver o que o plano Business inclui",
  "exports.whatTheseAre": "O que são estes ficheiros",
  "exports.about1": "Cada conjunto de dados é fornecido em CSV ou num livro de trabalho Excel real (.xlsx) — o livro de trabalho completo do inventário é apenas em Excel, com uma folha por conjunto de dados. Os ficheiros CSV abrem no Excel, no Numbers, no Google Sheets e na maioria das aplicações de stock. O texto em UTF-8, as vírgulas entre aspas, as quebras de linha nas notas e os zeros à esquerda nos códigos são todos preservados, e as células que começam como uma fórmula são neutralizadas para que uma folha de cálculo as abra como texto.",
  "exports.about2": "Nos ficheiros Excel, os SKU, UPC, ISBN e códigos de barras são células de texto — nunca em notação científica e nunca com zeros cortados — com larguras de coluna, filtros de cabeçalho e formatos de moeda ou de quantidade aplicados. O livro de trabalho completo do inventário mantém os produtos, os níveis de stock, as localizações e os movimentos em folhas separadas.",
  "exports.about3": "As exportações muito grandes param nas 20.000 linhas por conjunto de dados — quando isso acontece, o nome do ficheiro indica-o (truncated-20000), para que um ficheiro parcial nunca passe por completo.",
  "exports.about4": "Uma cópia de segurança é um instantâneo dos seus dados, não um restauro com um clique. Restaurá-la é um trabalho manual, feito com revisão prévia, por isso guarde o ficheiro em segurança — ainda nada na aplicação consegue recriar a partir dele uma empresa eliminada. O código da aplicação e as cópias de segurança da plataforma Base44 são tratados separadamente destes ficheiros.",
  "exports.about5": "As fotografias e os anexos são listados através das suas ligações guardadas — os próprios ficheiros de imagem não são incluídos na transferência.",
  "exports.backupTitle": "Cópia de segurança completa",
  "exports.backupDesc": "Um ficheiro com os produtos, as localizações, os níveis de stock, o registo completo de movimentos, os fornecedores, as compras, as encomendas, as devoluções, as contagens e os anúncios desta empresa — mais as definições do seu perfil. Guarde-o num local sob o seu controlo.",
  "exports.backupIncludes1": "Produtos, códigos, custos e notas",
  "exports.backupIncludes2": "Localizações e quantidades por localização",
  "exports.backupIncludes3": "Cada movimento, com autor e hora",
  "exports.backupIncludes4": "Compras, encomendas, devoluções e contagens",
  "exports.buildingBackup": "A criar a cópia de segurança…",
