  "print.templateIsBusiness": "{label} é uma funcionalidade do plano Business",
  "print.supplierBlockedDesc": "Os documentos de fornecedor fazem parte do plano Business — fornecedores, compras e ordens de compra. Tudo o que tem agora continua a funcionar.",
  "print.seeBusiness": "Ver o que o plano Business inclui",
  "print.nothingToPrint": "Ainda nada para imprimir",
  "print.pickOrderHint": "Escolha uma ordem de compra da lista para pré-visualizar o documento.",
  "print.pickCustomerOrderHint": "Escolha uma encomenda de cliente da lista para pré-visualizar o documento.",
  "print.pickReturnHint": "Escolha uma devolução registada da lista para pré-visualizar o documento.",
  "print.chooseStyleHint": "Escolha um estilo e depois escolha produtos da lista. A pré-visualização mostra exatamente o que sai da impressora.",
  "print.howToReach": "Como chegar à sua impressora",
  "print.howIntro": "Esta aplicação liga-se a impressoras que já possui — não é ela própria uma impressora. Há quatro formas de chegar a uma, e as etiquetas são impressas em ambos os planos através de qualquer uma delas. As guias de embalagem, as ordens de compra, os documentos de fornecedor e os relatórios são apenas do plano Business, seja qual for a ligação.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "A partir desta página, no Chrome ou no Edge para computador e no Chrome para Android: escolha a sua impressora de etiquetas e as etiquetas vão diretamente para ela. Não funciona no Safari do iOS — num iPhone, a impressão por Bluetooth vem com a aplicação móvel. Uma impressora que só fale Zebra ZPL ou a linguagem própria da Brother não vai compreender as etiquetas que esta página envia; isso é verificado em impressoras reais antes de ser dado como funcional.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Instale a impressora no Wi-Fi da sua loja e depois use o botão Imprimir — imprime através da impressora instalada neste computador, pela rede da loja. Num iPhone, o AirPrint está integrado: uma impressora AirPrint no mesmo Wi-Fi aparece simplesmente na folha de impressão, sem cabo e sem aplicação, e a aplicação não precisa de código específico para AirPrint. A impressora tem de suportar AirPrint (a maioria das novas suporta) e o telemóvel e a impressora têm de estar no mesmo Wi-Fi.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Ligue a impressora à rede da sua loja com um cabo Ethernet, instale-a no computador e imprima através do botão Imprimir. A Ethernet é um caminho para computadores — os iPhone não usam cabos Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Ligue a impressora ao computador com o seu cabo e use o botão Imprimir — imprime através da impressora aí instalada. Num telemóvel Android com um cabo USB OTG, o botão USB acima comunica diretamente com a impressora. Os iPhone não conseguem imprimir por USB diretamente — não há WebUSB — por isso use Wi-Fi / AirPrint, ou Bluetooth a partir da aplicação móvel.",
  "print.howCordsLead": "Os cabos continuam a servir os iPhone, com um passo intermédio.",
  "print.howCordsBody": "Uma impressora USB ligada ao computador da loja, ou uma impressora Ethernet ligada à rede, aparece no seu iPhone através do Wi-Fi da loja (AirPrint / impressora partilhada) — os cabos colocam a impressora na rede de forma sólida e o telemóvel chega a ela sem fios.",
  "print.howOfflineLead": "Se a internet cair,",
  "print.howOfflineBody": "as etiquetas e os documentos já presentes nesta página continuam a imprimir — o botão Imprimir, o PDF de etiquetas, o Bluetooth e o USB não precisam de ligação. O que precisa da internet é carregar a página e os seus produtos. O modo totalmente offline (trabalhar na aplicação sem qualquer ligação) é uma construção separada e maior, e não é aqui prometido.",
  "print.templatePrice": "Etiqueta de preço",
  "print.templatePriceHint": "Preço grande com nome e SKU",
  "print.templateShelf": "Etiqueta de prateleira",
