  "settings.cancelSubscription": "Cancelar Subscrição",
  "settings.cancelTerms.appleLink": "Instruções de cancelamento da Apple",
  "settings.cancelTerms.googlePlayLink": "Instruções de cancelamento do Google Play",
  "settings.cancelTerms.graceTitle": "Após o fim do período pago — 15 dias de tolerância e depois eliminação:",
  "settings.cancelTerms.intro": "Estes são os termos aplicáveis às subscrições pagas do Luminous StockHaven. A faturação das subscrições do site é feita através da Stripe. Pode cancelar a sua subscrição por si próprio, a qualquer momento, com o botão Cancelar Subscrição abaixo — não é necessária aprovação de funcionários. Os pedidos de cancelamento e de reembolso também podem ser tratados através do contacto oficial de apoio ao cliente, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Pode cancelar a sua subscrição por si próprio, a qualquer momento. Não é necessária aprovação de funcionários. As renovações futuras só param depois de o fornecedor de faturação confirmar o cancelamento.",
  "settings.cancelTerms.noApprovalTitle": "Cancelar sem aprovação:",
  "settings.cancelTerms.paymentBody": "Nos períodos experimentais pagos, o período experimental de sete dias exige um método de pagamento no registo. Salvo cancelamento dentro do prazo de cancelamento do período experimental aplicável, o plano mensal selecionado será cobrado automaticamente após o período experimental. O preço, a primeira data de faturação e o prazo de cancelamento específico do fornecedor têm de ser apresentados durante o registo. A faturação do período experimental é feita através da Stripe.",
  "settings.cancelTerms.paymentTitle": "Método de pagamento e renovação automática:",
  "settings.cancelTerms.remainingBody": "Se já pagou um período de faturação, pode manter o acesso até essa data de pagamento válido verificada. Uma cessação antecipada exige a confirmação adequada do fornecedor e o tratamento de qualquer reembolso aplicável. O acesso ao período experimental gratuito termina de acordo com a data de cessação do período experimental confirmada pelo fornecedor.",
  "settings.cancelTerms.remainingTitle": "Acesso restante:",
  "settings.cancelTerms.storesBody": "Se alguma vez subscrever através do Google Play ou da Apple App Store, a sua subscrição é faturada e gerida por essa loja. Poderá ter de a cancelar diretamente na secção de subscrições da mesma conta Google ou Apple utilizada para subscrever. Cancelar uma subscrição separada do site, desinstalar esta aplicação ou pedir a eliminação da conta Luminous StockHaven não cancela automaticamente uma subscrição faturada por uma loja. Verifique o recibo de compra para confirmar quem lhe cobra.",
  "settings.cancelTerms.storesTitle": "Subscrições do Google Play e da Apple App Store (se alguma vez subscrever através de uma loja):",
  "settings.cancelTerms.title": "Termos e Condições de Cancelamento",
