  "settings.trial.cancelKeeps": "Cancelar durante o período experimental mantém os seus 7 dias completos — o acesso termina em {date} e não lhe será cobrado nada.",
  "staff.access.noSeatBody": "A sua conta não tem lugar de funcionário nesta empresa, por isso o stock dela fica fechado. Peça ao proprietário que o adicione em Equipa e funções.",
  "staff.access.noSeatTitle": "Esta empresa não está aberta ao seu início de sessão",
  "staff.access.pendingBody": "Esta empresa tem um convite para o seu e-mail que ainda não foi ativado. Peça ao proprietário que defina o seu estado de funcionário como ativo. Nada aqui é visível até lá.",
  "staff.access.pendingTitle": "O seu convite ainda não está ativo",
  "staff.access.signOut": "Terminar sessão",
  "staff.access.suspendedBody": "Um administrador suspendeu esta conta de funcionário na empresa ativa. Peça-lhe que o volte a colocar como ativo e inicie sessão novamente.",
  "staff.access.suspendedTitle": "O seu acesso está suspenso",
  "staff.addFirst": "Adicionar o primeiro funcionário",
  "staff.addMember": "Adicionar funcionário",
  "staff.emptyBody": "Adicione uma pessoa, atribua-lhe uma função e as permissões correspondentes, e ela é convidada por e-mail a iniciar sessão nesta empresa.",
  "staff.emptyTitle": "Ainda sem funcionários",
  "staff.eyebrow": "Equipa",
  "staff.how.p1": "Cada membro tem uma função e a sua própria lista de permissões, por isso pode partir de uma função e alterar uma coisa sem criar uma função nova. Editar uma função não reescreve os membros que já a têm — abra um membro para reaplicar os valores predefinidos da sua função.",
  "staff.how.p2": "As funções personalizadas são uma funcionalidade do plano Business: o plano Essentials utiliza as cinco funções integradas (Proprietário, Gestor, Funcionário de stock, Funcionário de vendas, Visualizador).",
  "staff.how.p3": "Os convites são enviados por e-mail. Um membro só pode iniciar sessão depois de aceitar, e remover alguém desta lista não elimina a sua conta na aplicação.",
  "staff.how.p4": "Uma loja é a localização a que uma pessoa está atribuída. Fica registada no seu cartão; o que ela pode abrir continua a ser decidido pela sua função e permissões.",
  "staff.how.p5": "As permissões decidem o que cada pessoa pode abrir: os itens de menu fora da sua função ficam ocultos, e um endereço bloqueado mostra um aviso de «não está na sua função» em vez da página. Uma alteração aplica-se da próxima vez que essa pessoa carregar a aplicação; suspender um membro bloqueia-lhe totalmente o acesso.",
  "staff.how.p6": "Os administradores podem ver e alterar todos os dados, gerir os utilizadores e as funções da aplicação, e nunca são limitados por uma função de funcionário. Alguém sem registo de funcionário — o proprietário de uma empresa nova — mantém o acesso total.",
