  "printLib.usbUnavailable": "A impressão por USB a partir do website requer o Chrome para Android e um cabo USB OTG. Num computador, ligue a impressora ao computador e utilize o botão Imprimir — imprime através da impressora instalada nesse computador. Os iPhones não podem imprimir diretamente por USB — utilize o Wi-Fi com o AirPrint, ou o Bluetooth a partir da aplicação móvel (a chegar com a aplicação móvel).",
