  "payroll.dd.savings": "Conta poupança",
  "payroll.dd.steps.body": "1. Precisa de uma conta bancária empresarial que possa enviar pagamentos ACH. 2. Recolha um formulário de autorização assinado de cada membro da equipa — um cheque anulado ajuda a confirmar os números. 3. Envie o processamento salarial 2 a 3 dias úteis antes do dia de pagamento, para o dinheiro chegar a tempo. 4. A maioria dos estados exige o consentimento escrito do membro da equipa. Esta aplicação recolhe os formulários e acompanha-o em cada passo — o envio do dinheiro em si é feito através do seu próprio banco.",
