  "rewards.status.void": "Anulada",
  "rewards.subtitle": "Diga obrigado com uma recompensa — uma percentagem de desconto, um cartão-oferta, ou qualquer coisa que descreva.",
  "rewards.title": "Recompensas e incentivos",
  "rewards.value.giftCard": "Cartão-oferta de {value}",
  "rewards.value.percentOff": "{percent}% de desconto na loja",
  "rewards.void": "Anular",
  "rewards.voided": "Recompensa anulada.",
  "workforce.tab.rewards": "Recompensas",
  "training.lessons.mgr-give-rewards.step1": "Abra Equipa e toque em Recompensas. Escolha o membro da equipa e depois o tipo: uma percentagem de desconto na loja, um cartão-oferta, ou outra coisa que descreva nas suas próprias palavras.",
  "training.lessons.mgr-give-rewards.step2": "Dê à recompensa um nome curto e uma nota, se quiser. A pessoa recebe um sino de imediato, e a recompensa fica à espera nas As minhas recompensas dela, com o seu próprio código.",
  "training.lessons.mgr-give-rewards.step3": "O limite, por conceção: recompensa APENAS FUNCIONÁRIOS. Não pode recompensar-se a si próprio nem a outro gerente — recompensar um gerente é decisão do proprietário, e a aplicação recusa-o claramente.",
  "training.lessons.mgr-give-rewards.step4": "Na caixa, escreva o código que o membro da equipa lhe mostra e marque-o como utilizado — cada código funciona uma vez. Pode anular uma recompensa que deu, se os planos mudarem; as ofertas do proprietário são do proprietário para anular.",
  "training.lessons.mgr-give-rewards.title": "Dar recompensas aos seus funcionários",
  "training.lessons.owner-give-rewards.step1": "As recompensas vivem em Equipa, no separador Recompensas, e são apenas do plano Business — no Essentials, o separador mostra uma porta fechada, para que a sua equipa veja o que o plano maior contém.",
  "training.lessons.owner-give-rewards.step2": "Pode recompensar QUALQUER pessoa da equipa — funcionários e gerentes. Escolha a pessoa e depois o tipo: uma percentagem de desconto na loja (qualquer percentagem que escolha), um cartão-oferta para qualquer lugar, ou qualquer incentivo que descreva nas suas próprias palavras.",
  "training.lessons.owner-give-rewards.step3": "A recompensa chega com o seu próprio código de utilização única e toca o sino da pessoa. Ela mostra o código na caixa; um proprietário ou gerente escreve-o para o marcar como utilizado.",
  "training.lessons.owner-give-rewards.step4": "Um talão de recompensa impresso ou partilhado traz apenas o nome da SUA empresa — nunca o da aplicação. É o agradecimento da sua loja, não um anúncio.",
  "training.lessons.owner-give-rewards.title": "Dar recompensas (plano Business)",
  "training.lessons.owner-rewards-oversight.step1": "O seu gerente também pode dar recompensas — apenas a funcionários. A aplicação recusa um gerente a recompensar-se a si próprio ou a outro gerente; recompensar um gerente é sempre decisão sua.",
  "training.lessons.owner-rewards-oversight.step2": "Vê todas as recompensas da empresa no Histórico de recompensas: quem a deu, quem a recebeu e se está pronta, utilizada ou anulada. Um gerente vê apenas as recompensas que deu e as que recebeu.",
  "training.lessons.owner-rewards-oversight.step3": "Pode anular qualquer recompensa, incluindo uma que o seu gerente deu. Um gerente pode anular as suas próprias ofertas, mas nunca as suas.",
  "training.lessons.owner-rewards-oversight.step4": "Cada código funciona exatamente uma vez, e uma recompensa anulada nunca pode ser usada — o histórico mostra sempre como uma recompensa terminou.",
  "training.lessons.owner-rewards-oversight.title": "Supervisionar recompensas: as ofertas do seu gerente",
  "training.lessons.staff-your-rewards.step1": "Quando o seu gerente ou o proprietário lhe dá uma recompensa, o seu sino toca. Abra Equipa e toque em Recompensas para a ver em As minhas recompensas.",
  "training.lessons.staff-your-rewards.step2": "Cada recompensa tem o seu próprio código. Guarde-o para si — quem mostrar o código na caixa é quem usa a recompensa.",
  "training.lessons.staff-your-rewards.step3": "Para a usar, mostre o código quando comprar. A pessoa na caixa escreve-o e marca-o como utilizado — cada código funciona exatamente uma vez.",
  "training.lessons.staff-your-rewards.step4": "As recompensas são um mimo do plano Business. Se a sua loja não estiver no Business, o separador Recompensas mostra antes uma porta fechada — é o plano, não um erro.",
  "training.lessons.staff-your-rewards.title": "As suas recompensas: encontrar o seu código e usá-lo",
  "training.module.rewards": "Recompensas e incentivos",
